"""
Task management utility demonstrating basic CRUD operations.

This module shows how to structure a simple data management class
that students can extend with AI assistance.
"""

from typing import List, Dict, Any
from datetime import datetime


class TaskManager:
    """A simple task management system for demonstration purposes."""

    def __init__(self):
        self._tasks: List[Dict[str, Any]] = []
        self._next_id = 1

    def add_task(self, description: str, priority: str = "medium") -> int:
        """Add a new task and return its ID."""
        task = {
            "id": self._next_id,
            "description": description,
            "priority": priority,
            "completed": False,
            "created_at": datetime.now().isoformat()
        }
        self._tasks.append(task)
        self._next_id += 1
        return task["id"]

    def get_task(self, task_id: int) -> Dict[str, Any]:
        """Get a specific task by ID."""
        for task in self._tasks:
            if task["id"] == task_id:
                return task
        raise ValueError(f"Task with ID {task_id} not found")

    def get_all_tasks(self) -> List[Dict[str, Any]]:
        """Get all tasks."""
        return self._tasks.copy()

    def complete_task(self, task_id: int) -> None:
        """Mark a task as completed."""
        task = self.get_task(task_id)
        task["completed"] = True
        task["completed_at"] = datetime.now().isoformat()

    def delete_task(self, task_id: int) -> None:
        """Delete a task by ID."""
        self._tasks = [task for task in self._tasks if task["id"] != task_id]

    def to_dict(self) -> Dict[str, Any]:
        """Convert to dictionary for serialization."""
        return {
            "tasks": self._tasks,
            "next_id": self._next_id
        }

"""
File handling utility for data persistence.

This module demonstrates file I/O operations and error handling
patterns that students can learn from and extend.
"""

import json
import os
from typing import Any, Dict
from pathlib import Path


class FileHandler:
    """Handle file operations for data persistence."""

    def __init__(self, data_dir: str = "data"):
        self.data_dir = Path(data_dir)
        self.data_dir.mkdir(exist_ok=True)

    def save_data(self, filename: str, data: Dict[str, Any]) -> None:
        """Save data to a JSON file."""
        filepath = self.data_dir / filename
        try:
            with open(filepath, 'w', encoding='utf-8') as file:
                json.dump(data, file, indent=2, ensure_ascii=False)
        except (IOError, TypeError) as e:
            raise RuntimeError(f"Failed to save data to {filename}: {e}")

    def load_data(self, filename: str) -> Dict[str, Any]:
        """Load data from a JSON file."""
        filepath = self.data_dir / filename
        try:
            with open(filepath, 'r', encoding='utf-8') as file:
                return json.load(file)
        except FileNotFoundError:
            return {}
        except (IOError, json.JSONDecodeError) as e:
            raise RuntimeError(f"Failed to load data from {filename}: {e}")

    def file_exists(self, filename: str) -> bool:
        """Check if a file exists in the data directory."""
        return (self.data_dir / filename).exists()

    def delete_file(self, filename: str) -> None:
        """Delete a file from the data directory."""
        filepath = self.data_dir / filename
        if filepath.exists():
            filepath.unlink()

    def list_files(self) -> list[str]:
        """List all files in the data directory."""
        return [f.name for f in self.data_dir.iterdir() if f.is_file()]

